package com.example.reviewreminder;

import android.os.Bundle;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.Spinner;
import android.widget.TextView;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.concurrent.Future;

public final class TranslationActivity extends ScreenActivity {
    private WordUi ui;private String selectionId;private JSONArray words,current=new JSONArray();private int position,gradingMode;private Future<?> pending;private boolean generating,grading,active=true;private EditText answer,note;private SpeechManager speech;
    @Override public void onCreate(Bundle state){super.onCreate(state);ui=new WordUi(this);speech=new SpeechManager(this);selectionId=getIntent().getStringExtra("selectionId");try{JSONObject selection=TrainingStore.selection(this,selectionId);if(selection==null)throw new IllegalStateException("训练选词已失效");words=selection.getJSONArray("words");if(state!=null){current=new JSONArray(state.getString("current","[]"));position=state.getInt("position",0);}if(current.length()>0)showExercise();else showSetup();}catch(Exception e){ui.toast(e.getMessage());finish();}}
    @Override protected void onSaveInstanceState(Bundle out){saveCurrent();out.putString("current",current.toString());out.putInt("position",position);super.onSaveInstanceState(out);}

    private void showSetup(){
        saveCurrent();ui.start("AI 翻译训练");ui.body.addView(ui.text("已选 "+words.length()+" 个单词。题目生成后保存在本机，节省模式可离线作答。",13,WordUi.MUTED));ui.gap(ui.body,16);
        Spinner direction=new Spinner(this),count=new Spinner(this),difficulty=new Spinner(this),mode=new Spinner(this);direction.setAdapter(adapter(new String[]{"英译中（默认）","中译英"}));count.setAdapter(adapter(new String[]{"3 题","5 题","8 题","10 题"}));count.setSelection(1);difficulty.setAdapter(adapter(new String[]{"简单","适中","挑战"}));difficulty.setSelection(1);mode.setAdapter(adapter(new String[]{"节省模式：参考答案 + 自评","AI 问答批改：按需调用"}));for(Spinner s:new Spinner[]{direction,count,difficulty,mode}){s.setMinimumHeight(ui.dp(52));ui.body.addView(s);ui.gap(ui.body,8);}
        Button generate=ui.primaryButton("生成小批量题目",null);ui.body.addView(generate);generate.setOnClickListener(v->{if(generating)return;if(!AiSettings.ready(this)){ui.toast(AiSettings.notReadyMessage(this));return;}generating=true;generate.setEnabled(false);generate.setText("正在生成…");generate(direction,count,difficulty,mode,generate);});ui.gap(ui.body,20);
        ui.body.addView(ui.sectionLabel("历史题目 · 点击查看或再练"));JSONArray all=TranslationStore.all(this);if(all.length()==0)ui.body.addView(ui.text("暂无翻译练习",14,WordUi.MUTED));for(int i=all.length()-1;i>=0&&i>=all.length()-12;i--){JSONObject exercise=all.optJSONObject(i);if(exercise==null)continue;LinearLayout card=ui.card();card.addView(ui.text(exercise.optString("prompt"),15,WordUi.INK));card.addView(ui.text(("en_zh".equals(exercise.optString("direction"))?"英译中":"中译英")+" · "+(exercise.optString("selfRating").isEmpty()?"未完成":exercise.optString("selfRating")),12,WordUi.MUTED));card.setOnClickListener(v->{current=new JSONArray().put(exercise);position=0;showExercise();});Motion.press(card);ui.body.addView(card);ui.gap(ui.body,8);}
    }
    private ArrayAdapter<String> adapter(String[] values){return new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);}
    private void generate(Spinner direction,Spinner count,Spinner difficulty,Spinner mode,Button button){
        try{JSONArray targets=new JSONArray();int limit=Math.min(words.length(),20);for(int i=0;i<limit;i++){JSONObject w=words.optJSONObject(i);if(w!=null)targets.put(new JSONObject().put("english",w.optString("english")).put("chinese",w.optString("chinese")));}String dir=direction.getSelectedItemPosition()==0?"en_zh":"zh_en";String diff=difficulty.getSelectedItem().toString();int amount=Integer.parseInt(count.getSelectedItem().toString().replace(" 题",""));gradingMode=mode.getSelectedItemPosition();pending=AiClient.chatJson(this,AiPrompts.systemTranslation(),AiPrompts.userTranslation(targets.toString(),amount,dir,diff),new AiClient.Callback(){@Override public void onResult(JSONObject json){generating=false;if(isFinishing()||!active)return;button.setEnabled(true);button.setText("生成小批量题目");try{JSONArray items=json.optJSONArray("items");if(items==null||items.length()==0)throw new IllegalStateException("模型没有返回有效题目");JSONArray created=new JSONArray();for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null||item.optString("prompt").trim().isEmpty()||item.optString("reference").trim().isEmpty())continue;created.put(item);}if(created.length()==0)throw new IllegalStateException("题目字段不完整，请重试");current=new JSONArray();for(int i=0;i<created.length();i++){JSONObject item=created.getJSONObject(i);TranslationStore.add(TranslationActivity.this,TranslationStore.create(item,selectionId,dir,diff,gradingMode));}JSONArray all=TranslationStore.all(TranslationActivity.this);for(int i=0;i<created.length();i++)current.put(all.getJSONObject(all.length()-created.length()+i));position=0;showExercise();}catch(Exception e){ui.toast(e.getMessage());}}@Override public void onError(String message){generating=false;if(isFinishing()||!active)return;button.setEnabled(true);button.setText("重试生成");ui.toast(message+"；已有题目和答案未改动");}});}catch(Exception e){generating=false;button.setEnabled(true);button.setText("生成小批量题目");ui.toast(e.getMessage());}
    }

    private void showExercise(){
        if(current.length()==0){showSetup();return;}position=Math.max(0,Math.min(position,current.length()-1));note=null;JSONObject exercise=current.optJSONObject(position);gradingMode=exercise.optInt("gradingMode",0);ui.start("翻译练习");ui.body.addView(ui.text((position+1)+" / "+current.length()+" · "+("en_zh".equals(exercise.optString("direction"))?"英译中":"中译英")+" · "+exercise.optString("difficulty",""),13,WordUi.MUTED));ui.gap(ui.body,12);
        LinearLayout card=ui.card();TextView prompt=ui.text(exercise.optString("prompt"),21,WordUi.INK);prompt.setTypeface(null,android.graphics.Typeface.BOLD);card.addView(prompt);String speakText="en_zh".equals(exercise.optString("direction"))?exercise.optString("prompt"):exercise.optString("reference");prompt.setContentDescription("朗读英文："+speakText);prompt.setOnClickListener(v->speech.speak(speakText,"translation"));Motion.press(prompt);ui.body.addView(card);ui.gap(ui.body,12);
        answer=ui.field("你的翻译",exercise.optString("userAnswer"),4);ui.body.addView(ui.primaryButton(gradingMode==0?"保存并查看参考答案":"保存并 AI 批改",v->{saveCurrent();if(gradingMode==0)showReference(exercise);else grade(exercise);}));ui.gap(ui.body,8);
        TextView reference=ui.text("",15,WordUi.INK);reference.setVisibility(View.GONE);reference.setOnClickListener(v->speech.speak(speakText,"translation_answer"));Motion.press(reference);ui.body.addView(reference);ui.gap(ui.body,8);if(!exercise.optString("aiFeedback").isEmpty()){reference.setText(exercise.optString("aiFeedback"));reference.setVisibility(View.VISIBLE);}else if(exercise.optBoolean("referenceViewed")||!exercise.optString("selfRating").isEmpty()){reference.setText(referenceText(exercise));reference.setVisibility(View.VISIBLE);}
        if(gradingMode==0){note=ui.field("备注（可选）",exercise.optString("note"),2);LinearLayout ratings=ui.row();for(String label:new String[]{"正确","部分正确","错误"}){Button b=ui.secondaryButton(label,v->{saveCurrent();try{exercise.put("selfRating",label);TranslationStore.update(this,exercise);reference.setText(referenceText(exercise));reference.setVisibility(View.VISIBLE);ui.toast("已记录："+label);}catch(Exception e){ui.toast(e.getMessage());}});ratings.addView(b,new LinearLayout.LayoutParams(0,ui.dp(48),1));}ui.body.addView(ratings);}
        ui.gap(ui.body,12);LinearLayout navigation=ui.row();navigation.addView(ui.ghostButton("上一题",v->{saveCurrent();if(position>0){position--;showExercise();}else ui.toast("已经是第一题");}),new LinearLayout.LayoutParams(0,ui.dp(48),1));LinearLayout.LayoutParams nextLp=new LinearLayout.LayoutParams(0,ui.dp(48),1);nextLp.leftMargin=ui.dp(8);navigation.addView(ui.ghostButton(position+1<current.length()?"下一题":"完成",v->{saveCurrent();if(position+1<current.length()){position++;showExercise();}else showSetup();}),nextLp);ui.body.addView(navigation);ui.gap(ui.body,8);ui.body.addView(ui.ghostButton("加入目标词到错题本",v->addWrong(exercise)));ui.gap(ui.body,8);ui.body.addView(ui.textButton("以此题再练一次",v->{try{saveCurrent();JSONObject copy=TranslationStore.copyForRetry(exercise);TranslationStore.add(this,copy);current=new JSONArray().put(copy);position=0;showExercise();}catch(Exception e){ui.toast(e.getMessage());}}));
    }
    private void showReference(JSONObject exercise){try{exercise.put("referenceViewed",true);TranslationStore.update(this,exercise);}catch(Exception e){ui.toast(e.getMessage());}showExercise();}
    private String referenceText(JSONObject exercise){return "参考答案："+exercise.optString("reference")+(exercise.optString("explanation").isEmpty()?"":"\n"+exercise.optString("explanation"));}
    private void grade(JSONObject exercise){String value=answer.getText().toString().trim();if(value.isEmpty()){answer.setError("请先写下你的翻译");return;}if(grading){ui.toast("正在批改，请稍候");return;}grading=true;ui.toast("正在批改…");pending=AiClient.chatJson(this,AiPrompts.systemTranslationGrade(),AiPrompts.userTranslationGrade(exercise.optString("direction"),exercise.optString("prompt"),exercise.optString("reference"),value),new AiClient.Callback(){@Override public void onResult(JSONObject json){if(!active||isFinishing())return;grading=false;try{String text="判定："+json.optString("verdict")+"\n"+json.optString("feedback")+(json.optString("improved").isEmpty()?"":"\n改进译文："+json.optString("improved"));exercise.put("aiFeedback",text);TranslationStore.update(TranslationActivity.this,exercise);if(current.optJSONObject(position)==exercise)showExercise();}catch(Exception e){ui.toast(e.getMessage());}}@Override public void onError(String message){if(!active||isFinishing())return;grading=false;ui.toast(message+"；你的答案已保留，可重试");}});}
    private void addWrong(JSONObject exercise){try{JSONArray targets=exercise.optJSONArray("targets");int added=0;for(int i=0;i<words.length();i++){JSONObject word=words.optJSONObject(i);if(word==null)continue;boolean match=targets==null||targets.length()==0?words.length()==1:false;for(int j=0;targets!=null&&j<targets.length();j++)if(word.optString("english").equalsIgnoreCase(targets.optString(j)))match=true;if(match&&WrongBook.manualAdd(this,word.optLong("_taskId"),word.optInt("_wordIndex"),Words.stableId(word)))added++;}ui.toast(added==0?"未找到可加入的目标词":"已加入 "+added+" 个目标词；不影响拼写连续正确次数");}catch(Exception e){ui.toast(e.getMessage());}}
    private void saveCurrent(){if(answer==null||current==null||current.length()==0||position>=current.length())return;JSONObject exercise=current.optJSONObject(position);try{exercise.put("userAnswer",answer.getText().toString());if(note!=null)exercise.put("note",note.getText().toString());TranslationStore.update(this,exercise);}catch(Exception e){ui.toast("答案暂未保存："+e.getMessage());}}
    @Override public void onBackPressed(){saveCurrent();if(ui.body!=null&&current.length()>0){current=new JSONArray();showSetup();}else super.onBackPressed();}
    @Override protected void onPause(){saveCurrent();speech.stop();super.onPause();}
    @Override protected void onDestroy(){active=false;AiClient.cancel(pending);speech.shutdown();super.onDestroy();}
}
